"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import {
  ArrowUpIcon,
  BrainIcon,
  ChevronDownIcon,
  FolderOpenIcon,
  PlusIcon,
  ShieldIcon,
} from "@/components/icons";

function SelectorButton({
  icon,
  label,
}: {
  icon: React.ReactNode;
  label: string;
}) {
  return (
    <button
      type="button"
      className="flex h-8 items-center gap-1.5 rounded-[8px] px-2.5 text-[13px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
    >
      <span className="text-current">{icon}</span>
      <span className="whitespace-nowrap">{label}</span>
      <ChevronDownIcon size={12} className="text-fg-muted" />
    </button>
  );
}

export function Composer({
  placeholder,
  modelLabel = "Default Model",
  permissionLabel = "Don't Ask",
  showModel = true,
  glow = false,
  workInProject = false,
}: {
  placeholder: string;
  modelLabel?: string;
  permissionLabel?: string;
  showModel?: boolean;
  glow?: boolean;
  workInProject?: boolean;
}) {
  const [value, setValue] = useState("");
  const hasText = value.trim().length > 0;

  return (
    <div
      className={cn(
        "overflow-hidden rounded-[16px] border border-border-base bg-bg-2/60 backdrop-blur-sm",
        glow && "aou-composer-glow border-brand-light",
      )}
    >
      <div className="px-4 pt-3.5">
        <textarea
          value={value}
          onChange={(e) => setValue(e.target.value)}
          rows={2}
          placeholder={placeholder}
          className="max-h-40 min-h-[40px] w-full resize-none bg-transparent text-[15px] leading-relaxed text-fg outline-none placeholder:text-fg-muted"
        />
      </div>

      <div className="flex items-center justify-between gap-2 px-3 pb-3">
        <button
          type="button"
          aria-label="Add attachment"
          className="flex h-8 w-8 items-center justify-center rounded-full bg-bg-3 text-fg-secondary transition-colors hover:bg-bg-4 hover:text-fg"
        >
          <PlusIcon size={16} />
        </button>

        <div className="flex items-center gap-1">
          {showModel && (
            <SelectorButton icon={<BrainIcon size={14} />} label={modelLabel} />
          )}
          <SelectorButton icon={<ShieldIcon size={14} />} label={permissionLabel} />
          <button
            type="button"
            aria-label="Send"
            className={cn(
              "ml-1 flex h-8 w-8 items-center justify-center rounded-full transition-all",
              hasText
                ? "aou-brand-gradient text-white"
                : "bg-bg-3 text-fg-secondary hover:bg-bg-4",
            )}
          >
            <ArrowUpIcon size={16} />
          </button>
        </div>
      </div>

      {workInProject && (
        <button
          type="button"
          className="flex w-full items-center gap-2 border-t border-border-base px-4 py-2.5 text-left text-[13px] text-fg-secondary transition-colors hover:bg-bg-hover"
        >
          <FolderOpenIcon size={14} />
          <span>Work in a project</span>
        </button>
      )}
    </div>
  );
}
