"use client";

import { cn } from "@/lib/utils";
import {
  ChevronDownIcon,
  ClockIcon,
  FolderIcon,
  HistoryIcon,
  LogoIcon,
  LogoutIcon,
  MoreIcon,
  PlusIcon,
  SearchIcon,
  SettingsIcon,
} from "@/components/icons";
import { CONVERSATIONS, PROJECTS } from "@/lib/mock-data";
import { useApp } from "./AppContext";

function BrandHeader() {
  return (
    <div className="flex h-[52px] items-center gap-2.5 px-4">
      <div className="flex h-7 w-7 items-center justify-center rounded-[8px] bg-[#1c1c1e] text-white">
        <LogoIcon size={20} />
      </div>
      <span className="text-[16px] font-semibold text-fg">AionUi</span>
    </div>
  );
}

function NavRow({
  icon,
  label,
  active,
  onClick,
  trailing,
}: {
  icon: React.ReactNode;
  label: string;
  active?: boolean;
  onClick?: () => void;
  trailing?: React.ReactNode;
}) {
  return (
    <div
      onClick={onClick}
      className={cn(
        "group flex h-9 cursor-pointer items-center gap-2.5 rounded-[8px] px-2.5 text-[14px] transition-colors",
        active
          ? "bg-bg-active text-fg"
          : "text-fg-secondary hover:bg-bg-hover hover:text-fg",
      )}
    >
      <span className="flex w-4 shrink-0 items-center justify-center text-current">
        {icon}
      </span>
      <span className="flex-1 truncate">{label}</span>
      {trailing}
    </div>
  );
}

function SectionLabel({
  label,
  trailing,
}: {
  label: string;
  trailing?: React.ReactNode;
}) {
  return (
    <div className="flex h-7 items-center gap-1 px-2.5 text-[12px] font-medium text-fg-muted">
      <span className="flex-1">{label}</span>
      {trailing}
    </div>
  );
}

export function Sidebar() {
  const {
    sidebarCollapsed,
    toggleSidebar,
    goHome,
    goScheduled,
    goSettings,
    openConversation,
    activeConversationId,
    screen,
    setSearchOpen,
  } = useApp();

  return (
    <>
      {/* mobile backdrop */}
      {!sidebarCollapsed && (
        <div
          className="fixed inset-0 top-9 z-30 bg-black/40 md:hidden"
          onClick={toggleSidebar}
          aria-hidden
        />
      )}
      <aside
        className={cn(
          "layout-sider z-40 flex h-full shrink-0 flex-col overflow-hidden border-r border-border-base bg-bg-2",
          "max-md:fixed max-md:inset-y-0 max-md:left-0 max-md:top-9",
          "transition-[width,transform] duration-200 ease-[cubic-bezier(0.34,0.69,0.1,1)]",
          sidebarCollapsed
            ? "w-0 border-r-0 max-md:w-[260px] max-md:-translate-x-full"
            : "w-[260px]",
        )}
      >
        <div className="flex h-full w-[260px] flex-col">
          <BrandHeader />

          {/* scrollable nav */}
          <div className="flex-1 overflow-y-auto px-2 pb-2">
            <NavRow
              icon={<PlusIcon size={14} />}
              label="New Chat"
              active={screen === "home"}
              onClick={goHome}
              trailing={
                <button
                  type="button"
                  aria-label="Chat history"
                  className="flex h-6 w-6 items-center justify-center rounded-[6px] text-fg-muted opacity-0 transition group-hover:opacity-100 hover:bg-bg-3 hover:text-fg"
                  onClick={(e) => e.stopPropagation()}
                >
                  <HistoryIcon size={15} />
                </button>
              }
            />
            <NavRow
              icon={<SearchIcon size={16} />}
              label="Search"
              onClick={() => setSearchOpen(true)}
            />
            <NavRow
              icon={<ClockIcon size={16} />}
              label="Scheduled Tasks"
              active={screen === "scheduled"}
              onClick={goScheduled}
            />

            {/* Teams */}
            <div className="mt-3">
              <SectionLabel
                label="Teams"
                trailing={
                  <button
                    type="button"
                    aria-label="Add team"
                    className="flex h-5 w-5 items-center justify-center rounded text-fg-muted hover:bg-bg-3 hover:text-fg"
                  >
                    <PlusIcon size={12} />
                  </button>
                }
              />

              {/* Projects */}
              <div className="mt-1">
                <SectionLabel
                  label="Projects"
                  trailing={<ChevronDownIcon size={12} className="text-fg-muted" />}
                />
                {PROJECTS.map((p) => (
                  <div key={p.id}>
                    <NavRow icon={<FolderIcon size={15} />} label={p.name} />
                    <div className="ml-3 border-l border-border-base pl-1.5">
                      {p.conversations.map((c) => (
                        <NavRow
                          key={c.id}
                          icon={
                            <span className="grid h-4 w-4 place-items-center rounded-full bg-[#d97757] text-[9px]">
                              ✳
                            </span>
                          }
                          label={c.title}
                          active={activeConversationId === c.id}
                          onClick={() => openConversation(c.id)}
                        />
                      ))}
                    </div>
                  </div>
                ))}
              </div>

              {/* Conversations */}
              <div className="mt-1">
                <SectionLabel
                  label="Conversations"
                  trailing={<ChevronDownIcon size={12} className="text-fg-muted" />}
                />
                {CONVERSATIONS.map((c) => (
                  <NavRow
                    key={c.id}
                    icon={<span className="text-[15px] leading-none">{c.emoji}</span>}
                    label={c.title}
                    active={activeConversationId === c.id}
                    onClick={() => openConversation(c.id)}
                    trailing={
                      <button
                        type="button"
                        aria-label="More"
                        className="flex h-6 w-6 items-center justify-center rounded-[6px] text-fg-muted opacity-0 transition group-hover:opacity-100 hover:bg-bg-3 hover:text-fg"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <MoreIcon size={14} />
                      </button>
                    }
                  />
                ))}
              </div>
            </div>
          </div>

          {/* footer */}
          <div className="flex items-center gap-1 border-t border-border-base px-2 py-2.5">
            <button
              type="button"
              onClick={goSettings}
              className={cn(
                "flex h-9 flex-1 items-center gap-2 rounded-[8px] px-2.5 text-[14px] transition-colors",
                screen === "settings"
                  ? "bg-bg-active text-fg"
                  : "text-fg-secondary hover:bg-bg-hover hover:text-fg",
              )}
            >
              <SettingsIcon size={16} />
              <span>Settings</span>
            </button>
            <button
              type="button"
              className="flex h-9 flex-1 items-center gap-2 rounded-[8px] px-2.5 text-[14px] text-fg-secondary transition-colors hover:bg-bg-hover hover:text-fg"
            >
              <LogoutIcon size={16} />
              <span>Logout</span>
            </button>
          </div>
        </div>
      </aside>
    </>
  );
}
