"use client";

import { cn } from "@/lib/utils";
import { InfoIcon, PlusIcon } from "@/components/icons";
import { useApp } from "../AppContext";
import type { ThemeName } from "@/types";

function Card({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <div
      className={cn(
        "rounded-[16px] border border-border-base bg-bg-2/40 p-6",
        className,
      )}
    >
      {children}
    </div>
  );
}

function OutlineButton({
  children,
  icon,
}: {
  children: React.ReactNode;
  icon?: React.ReactNode;
}) {
  return (
    <button
      type="button"
      className="flex h-8 items-center gap-1.5 rounded-[8px] border border-border-base px-3 text-[13px] text-fg-secondary transition-colors hover:border-border-special hover:bg-bg-hover hover:text-fg"
    >
      {icon}
      {children}
    </button>
  );
}

function ModelPage() {
  return (
    <Card>
      <div className="flex items-center justify-between">
        <h1 className="text-[20px] font-semibold text-fg">Model</h1>
        <div className="flex items-center gap-2">
          <OutlineButton>Clear status</OutlineButton>
          <OutlineButton icon={<PlusIcon size={13} />}>Add Model</OutlineButton>
        </div>
      </div>

      <div className="mt-4 rounded-[10px] border border-border-base bg-bg-1/50 px-4 py-2.5 text-[13px] text-fg-muted">
        Note: Only Aion CLI currently supports custom models.
      </div>

      <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
        <div className="flex h-14 w-14 items-center justify-center rounded-full border-2 border-border-special text-fg-muted">
          <InfoIcon size={26} />
        </div>
        <h3 className="text-[16px] font-semibold text-fg">No configured models</h3>
        <p className="text-[14px] text-fg-secondary">
          Need help? Check out the detailed{" "}
          <a className="text-accent-blue underline-offset-2 hover:underline">
            configuration guide
          </a>
          .
        </p>
      </div>
    </Card>
  );
}

const THEME_CARDS: { id: string; name: string; theme?: ThemeName; preview: React.ReactNode }[] = [
  {
    id: "light",
    name: "Light",
    theme: "light",
    preview: (
      <div className="flex h-full w-full flex-col items-center justify-center gap-1 bg-gradient-to-b from-[#e9ecf6] to-white">
        <div className="h-5 w-9 rounded-md bg-[#1c1c1e]" />
        <span className="text-[13px] font-semibold text-[#5b6cc4]">AionUi</span>
      </div>
    ),
  },
  {
    id: "dark",
    name: "Dark",
    theme: "dark",
    preview: (
      <div className="flex h-full w-full flex-col justify-center gap-1.5 bg-[#14161c] px-3">
        <span className="h-1.5 w-1.5 rounded-full bg-[#4d9fff]" />
        <div className="h-1.5 w-10 rounded-full bg-[#3a3f4a]" />
        <div className="h-1.5 w-16 rounded-full bg-[#3a3f4a]" />
        <div className="ml-auto h-1.5 w-12 rounded-full bg-[#2f6df0]" />
      </div>
    ),
  },
  {
    id: "misaka",
    name: "Misaka Mikoto Theme",
    preview: <div className="h-full w-full bg-gradient-to-br from-[#f4d9c6] to-[#caa] " />,
  },
  {
    id: "kitty",
    name: "Hello Kitty",
    preview: (
      <div className="flex h-full w-full items-center justify-center bg-white">
        <span className="text-[20px]">🎀</span>
      </div>
    ),
  },
  {
    id: "retro",
    name: "Retro Windows",
    preview: <div className="h-full w-full bg-gradient-to-b from-[#5aa0e6] to-[#2e6fb0]" />,
  },
];

function ThemeCard({
  card,
  selected,
  onClick,
}: {
  card: (typeof THEME_CARDS)[number];
  selected: boolean;
  onClick?: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "group relative overflow-hidden rounded-[10px] border-2 text-left transition-colors",
        selected ? "border-accent-blue" : "border-border-base hover:border-border-special",
      )}
    >
      <div className="aspect-[16/9] w-full overflow-hidden">{card.preview}</div>
      <div className="bg-bg-1/80 px-2.5 py-1.5 text-[12px] font-medium text-fg">
        {card.name}
      </div>
      {selected && (
        <span className="absolute right-1.5 top-1.5 flex h-4 w-4 items-center justify-center rounded-full bg-accent-blue text-[10px] text-white">
          ✓
        </span>
      )}
    </button>
  );
}

function FontRow({ label, value }: { label: string; value: number }) {
  return (
    <div className="flex items-center justify-between py-3">
      <span className="text-[14px] text-fg">{label}</span>
      <div className="flex items-center gap-2">
        <button className="flex h-7 w-7 items-center justify-center rounded-full bg-bg-3 text-fg-secondary hover:bg-bg-4">
          −
        </button>
        <span className="w-7 text-center text-[14px] text-fg">{value}</span>
        <button className="flex h-7 w-7 items-center justify-center rounded-full bg-bg-3 text-fg-secondary hover:bg-bg-4">
          +
        </button>
        <button className="ml-1 text-[13px] text-fg-muted hover:text-fg-secondary">
          Reset
        </button>
      </div>
    </div>
  );
}

function AppearancePage() {
  const { theme, setTheme } = useApp();
  return (
    <div className="flex flex-col gap-4">
      <Card>
        <div className="flex items-start justify-between">
          <div>
            <h2 className="text-[16px] font-semibold text-fg">Theme</h2>
            <p className="mt-1 text-[13px] text-fg-muted">
              Select or customize a theme
            </p>
          </div>
          <OutlineButton icon={<PlusIcon size={13} />}>Add Manually</OutlineButton>
        </div>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
          {THEME_CARDS.map((c) => (
            <ThemeCard
              key={c.id}
              card={c}
              selected={c.theme === theme}
              onClick={c.theme ? () => setTheme(c.theme!) : undefined}
            />
          ))}
        </div>
      </Card>

      <Card className="py-2">
        <FontRow label="Chat text size" value={16} />
        <div className="border-t border-border-base" />
        <FontRow label="Markdown text size" value={15} />
        <div className="border-t border-border-base" />
        <FontRow label="Code font size" value={13} />
      </Card>

      <Card>
        <div className="flex items-center justify-between gap-4">
          <span className="text-[14px] text-fg">Scale</span>
          <div className="flex flex-1 items-center gap-3">
            <button className="flex h-7 w-7 items-center justify-center rounded-full bg-bg-3 text-fg-secondary hover:bg-bg-4">
              −
            </button>
            <input
              type="range"
              min={50}
              max={150}
              defaultValue={100}
              className="h-1 flex-1 accent-[var(--primary)]"
            />
            <button className="flex h-7 w-7 items-center justify-center rounded-full bg-bg-3 text-fg-secondary hover:bg-bg-4">
              +
            </button>
            <span className="text-[14px] text-fg">100%</span>
            <button className="text-[13px] text-fg-muted hover:text-fg-secondary">
              Reset zoom
            </button>
          </div>
        </div>
      </Card>
    </div>
  );
}

function PlaceholderPage({ title }: { title: string }) {
  return (
    <Card>
      <h1 className="text-[20px] font-semibold text-fg">{title}</h1>
      <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
        <div className="flex h-14 w-14 items-center justify-center rounded-full border-2 border-border-special text-fg-muted">
          <InfoIcon size={26} />
        </div>
        <p className="text-[14px] text-fg-secondary">
          {title} settings for this AionUi clone.
        </p>
      </div>
    </Card>
  );
}

const TITLES: Record<string, string> = {
  agents: "Agents",
  capabilities: "Capabilities",
  remote: "Remote",
  system: "System",
  about: "About",
};

export function SettingsScreen() {
  const { settingsSection } = useApp();

  return (
    <div className="h-full overflow-y-auto p-5">
      <div className="mx-auto max-w-[1040px]">
        {settingsSection === "model" && <ModelPage />}
        {settingsSection === "appearance" && <AppearancePage />}
        {settingsSection in TITLES && <PlaceholderPage title={TITLES[settingsSection]} />}
      </div>
    </div>
  );
}
