import { Fragment, type ReactNode } from "react";

/*
  Minimal markdown renderer tuned to AionUi's assistant-message styling.
  Supports: #/##/### headings, **bold**, `inline code`, - bullet lists,
  1. ordered lists, > blockquotes, --- rules, and paragraphs.
  Deliberately dependency-free so the build stays self-contained.
*/

function renderInline(text: string, keyBase: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  // Split on **bold** and `code`, keeping delimiters.
  const regex = /(\*\*[^*]+\*\*|`[^`]+`)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    const token = match[0];
    if (token.startsWith("**")) {
      nodes.push(
        <strong key={`${keyBase}-b${i}`} className="font-semibold text-fg">
          {token.slice(2, -2)}
        </strong>,
      );
    } else {
      nodes.push(
        <code
          key={`${keyBase}-c${i}`}
          className="rounded-[4px] bg-bg-3/80 px-[5px] py-[1px] font-mono text-[var(--code-font-size)] text-fg"
        >
          {token.slice(1, -1)}
        </code>,
      );
    }
    lastIndex = match.index + token.length;
    i += 1;
  }
  if (lastIndex < text.length) nodes.push(text.slice(lastIndex));
  return nodes;
}

export function Markdown({ content }: { content: string }) {
  const lines = content.split("\n");
  const blocks: ReactNode[] = [];
  let i = 0;
  let key = 0;

  while (i < lines.length) {
    const line = lines[i];

    // blank line
    if (line.trim() === "") {
      i += 1;
      continue;
    }

    // horizontal rule
    if (/^---+$/.test(line.trim())) {
      blocks.push(<hr key={key++} className="my-6 border-0 border-t border-border-base" />);
      i += 1;
      continue;
    }

    // headings
    const heading = line.match(/^(#{1,4})\s+(.*)$/);
    if (heading) {
      const level = heading[1].length;
      const sizes = ["text-[22px]", "text-[19px]", "text-[17px]", "text-[15px]"];
      blocks.push(
        <p
          key={key++}
          className={`mt-5 mb-2 font-semibold text-fg ${sizes[level - 1]}`}
        >
          {renderInline(heading[2], `h${key}`)}
        </p>,
      );
      i += 1;
      continue;
    }

    // blockquote (consume consecutive > lines)
    if (line.trimStart().startsWith(">")) {
      const quote: string[] = [];
      while (i < lines.length && lines[i].trimStart().startsWith(">")) {
        quote.push(lines[i].replace(/^\s*>\s?/, ""));
        i += 1;
      }
      blocks.push(
        <blockquote
          key={key++}
          className="my-3 rounded-r-[6px] border-l-[3px] border-border-special bg-message-tips/60 px-4 py-2.5 text-[var(--md-font-size)] leading-[1.7] text-fg-secondary"
        >
          {quote.map((q, qi) => (
            <p key={qi} className={qi > 0 ? "mt-2" : ""}>
              {renderInline(q, `q${key}-${qi}`)}
            </p>
          ))}
        </blockquote>,
      );
      continue;
    }

    // unordered list
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i += 1;
      }
      blocks.push(
        <ul key={key++} className="my-3 ml-5 list-disc space-y-1.5 text-[var(--md-font-size)] leading-[1.7] text-fg marker:text-fg-muted">
          {items.map((it, ii) => (
            <li key={ii} className="pl-1">
              {renderInline(it, `ul${key}-${ii}`)}
            </li>
          ))}
        </ul>,
      );
      continue;
    }

    // ordered list
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i += 1;
      }
      blocks.push(
        <ol key={key++} className="my-3 ml-5 list-decimal space-y-2 text-[var(--md-font-size)] leading-[1.7] text-fg marker:text-fg-muted">
          {items.map((it, ii) => (
            <li key={ii} className="pl-1">
              {renderInline(it, `ol${key}-${ii}`)}
            </li>
          ))}
        </ol>,
      );
      continue;
    }

    // paragraph (consume until blank / block start)
    const para: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !lines[i].trimStart().startsWith(">") &&
      !/^(#{1,4})\s+/.test(lines[i]) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i += 1;
    }
    blocks.push(
      <p
        key={key++}
        className="my-3 text-[var(--md-font-size)] leading-[1.75] text-fg first:mt-0"
      >
        {para.map((p, pi) => (
          <Fragment key={pi}>
            {pi > 0 && <br />}
            {renderInline(p, `p${key}-${pi}`)}
          </Fragment>
        ))}
      </p>,
    );
  }

  return <div className="aou-markdown">{blocks}</div>;
}
